const CONJ_VERBS=[['書く','五段','かく'],['泳ぐ','五段','およぐ'],['話す','五段','はなす'],['待つ','五段','まつ'],['買う','五段','かう'],['読む','五段','よむ'],['遊ぶ','五段','あそぶ'],['死ぬ','五段','しぬ'],['帰る','五段','かえる'],['行く','五段','いく'],['食べる','一段','たべる'],['見る','一段','みる'],['起きる','一段','おきる'],['する','サ变','する'],['来る','カ变','くる']];
const FORMS=['ます形','ません形','ました形','ませんでした形','ない形','なかった形','て形','た形','可能形','受身形','使役形','使役被动形','意向形','ば形','命令形','禁止形','たい形'];
function conjugate(w,type){
 const last=w.slice(-1),stem=w.slice(0,-1);let m,neg,te,ta,pot,pass,cause,vol,ba,imp;
 if(type==='サ变'){const s=w.endsWith('する')?w.slice(0,-2):'';m=s+'し';neg=s+'しない';te=s+'して';ta=s+'した';pot=s+'できる';pass=s+'される';cause=s+'させる';vol=s+'しよう';ba=s+'すれば';imp=s+'しろ';}
 else if(type==='カ变'){const s=w.endsWith('来る')?w.slice(0,-2):w.endsWith('くる')?w.slice(0,-2):'';const c=w.endsWith('来る')?'来':'';m=s+(c||'き');neg=s+(c||'こ')+'ない';te=s+(c||'き')+'て';ta=s+(c||'き')+'た';pot=s+(c||'こ')+'られる';pass=pot;cause=s+(c||'こ')+'させる';vol=s+(c||'こ')+'よう';ba=s+(c||'く')+'れば';imp=s+(c||'こ')+'い';}
 else if(type==='一段'){m=stem;neg=stem+'ない';te=stem+'て';ta=stem+'た';pot=stem+'られる';pass=pot;cause=stem+'させる';vol=stem+'よう';ba=stem+'れば';imp=stem+'ろ';}
 else{const u='うくぐすつぬぶむる',a='わかがさたなばまら',i='いきぎしちにびみり',e='えけげせてねべめれ',o='おこごそとのぼもろ',ix=u.indexOf(last);if(ix<0)return null;m=stem+i[ix];neg=stem+a[ix]+'ない';const t=['って','いて','いで','して','って','んで','んで','んで','って'][ix];te=stem+t;if(w==='行く'||w==='いく')te=stem+'って';ta=te.replace(/て$/,'た').replace(/で$/,'だ');pot=stem+e[ix]+'る';pass=stem+a[ix]+'れる';cause=stem+a[ix]+'せる';vol=stem+o[ix]+'う';ba=stem+e[ix]+'ば';imp=stem+e[ix];}
 return {'ます形':m+'ます','ません形':m+'ません','ました形':m+'ました','ませんでした形':m+'ませんでした','ない形':neg,'なかった形':neg.slice(0,-1)+'かった','て形':te,'た形':ta,'可能形':pot,'受身形':pass,'使役形':cause,'使役被动形':cause.slice(0,-1)+'られる','意向形':vol,'ば形':ba,'命令形':imp,'禁止形':w+'な','たい形':m+'たい'};
}
const CONJ_ITEMS=CONJ_VERBS.flatMap(([word,type,reading],j)=>FORMS.map((form,i)=>({id:'c-'+j+'-'+i,level:'活用',conj:true,wordBase:word,verbType:type,kanaBase:reading,form})));
CONJ_ITEMS.forEach(x=>MAP.set(x.id,x));
let conjWord='書く',conjType='五段';
function conjugation(){return heading('CONJUGATION STUDIO','活用工坊','先确定动词类型，再观察词形变化。工具生成规范基本式；敬语、不规则惯用表达与缩约式请结合专题学习。',btn('活用输入训练 ↗','conj-quiz','','primary'))+`<div class="panel"><label>常用动词示范</label><div class="chips">${CONJ_VERBS.map(([w,t])=>btn(w,'conj-example',w,'chip '+(w===conjWord?'active':''))).join('')}</div><div class="toolbar"><input id="conj-word" aria-label="辞书形" value="${E(conjWord)}" placeholder="输入辞书形，例如：勉強する"><select id="conj-type" aria-label="动词类型">${['五段','一段','サ变','カ变','い形容词','な形容词','名词'].map(t=>`<option ${t===conjType?'selected':''}>${t}</option>`).join('')}</select>${btn('生成活用表','conj-render','','primary')}</div><p class="small muted">来る保留汉字时读音会变化：来ます（きます）、来ない（こない）、来れば（くれば）。请勿仅按词尾る猜类型。い形容词いい／かっこいい使用よい系活用。</p><div id="conj-output">${conjTable()}</div></div><div class="grid2"><div class="panel"><h3>五段音便口诀</h3><p class="jp">う・つ・る → って<br>む・ぶ・ぬ → んで<br>く → いて ／ ぐ → いで<br>す → して</p><p class="muted">行く → 行って；た形将て／で换为た／だ。</p></div><div class="panel"><h3>先看结构，再背形式</h3><p>可能和被动的一段形式相同，语义靠上下文区分。使役被动先生成使役的一段形，再变被动。</p>${btn('阅读动词活用总图','detail','f6')}${btn('阅读形容词活用','detail','f7','text-btn')}</div></div>`;}
function conjTable(){let out;if(['い形容词','な形容词','名词'].includes(conjType)){if(conjType==='い形容词'){if(!conjWord.endsWith('い'))return '<p class="note">请输入以い结尾的い形容词。</p>';let st=conjWord==='いい'?'よ':conjWord.endsWith('いい')?conjWord.slice(0,-2)+'よ':conjWord.slice(0,-1);out={'基本形':conjWord,'否定':st+'くない','过去':st+'かった','过去否定':st+'くなかった','て形':st+'くて','条件形':st+'ければ','副词形':st+'く'};}else{const st=conjWord.replace(/だ$/,'');out={'基本判断':st+'だ','礼貌体':st+'です','否定':st+'ではない','过去':st+'だった','过去否定':st+'ではなかった','连接':st+'で','条件':st+'なら','修饰名词':st+(conjType==='名词'?'の':'な')};if(conjType!=='名词')out['副词形']=st+'に';}}else{if(conjType==='一段'&&!conjWord.endsWith('る')||conjType==='サ变'&&!conjWord.endsWith('する')||conjType==='カ变'&&!/(来る|くる)$/.test(conjWord))return '<p class="note">输入词尾与所选类型不符，请检查辞书形。</p>';out=conjugate(conjWord,conjType);}return out?`<div class="scroll"><table><thead><tr><th>形式</th><th>结果</th></tr></thead><tbody>${Object.entries(out).map(([k,v])=>`<tr><td>${k}</td><td class="jp">${E(v)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="note">无法生成，请输入有效辞书形并选择正确类型。</p>';}
function topics(){return heading('CONTRAST & CONTEXT','辨析与专题',`${T.length}个深入专题：比较接续、语气、证据、责任和使用场景。每课含成对例句与独立语境题。`)+chips(['N5','N4','N3','N2','N1'])+toolbar('搜索辨析、句型或语境…',false)+`<div class="grid3">${T.filter(x=>(filterLevel==='全部'||x.level===filterLevel)&&(!search||JSON.stringify(x).includes(search))).map(x=>`<article class="card">${badge(x.level)}<h3 style="margin-top:16px">${E(x.title)}</h3><p>${E(x.paragraphs[0].slice(0,80))}…</p>${btn('阅读辨析','detail',x.id)} ${btn('语境练习','topic-quiz',x.id,'primary')}${actions(x)}</article>`).join('')}</div>`;}
function reading(){const list=R.filter(x=>(filterLevel==='全部'||x.level===filterLevel)&&(!search||JSON.stringify(x).toLowerCase().includes(search.toLowerCase()))&&(readingGenre==='全部'||(x.genre||'分级短文')===readingGenre)&&(readingStatus==='全部'||readingStatus==='未读完'&&!state.completed[x.id]||readingStatus==='已读完'&&state.completed[x.id]));page=Math.min(page,Math.max(1,Math.ceil(list.length/24)));return heading('READING ROOM','读进一个新的世界',`${R.length}篇原创阅读 · N5～N1各50篇 · 共${RQ.length}道理解题。先独立阅读，再看解析与中文内容对照。`)+chips(['N5','N4','N3','N2','N1'])+toolbar('搜索文章标题、内容或中文对照…',false)+`<div class="toolbar"><label>阅读类型<select id="reading-genre">${['全部',...new Set(R.map(x=>x.genre||'分级短文'))].map(g=>`<option ${g===readingGenre?'selected':''}>${E(g)}</option>`).join('')}</select></label><label>完成状态<select id="reading-status">${['全部','未读完','已读完'].map(t=>`<option ${readingStatus===t?'selected':''}>${t}</option>`).join('')}</select></label>${btn(state.profile.ruby?'注音：开':'注音：关','ruby')}</div><div class="grid3">${list.slice((page-1)*24,page*24).map(x=>`<article class="card">${badge(x.level)}<h2 class="jp">${JP(x.title)}</h2><p>${E(x.text.slice(0,66))}…</p><p class="small">${E(x.genre||'分级短文')} · ${[...x.text.replace(/\s/g,'')].length} 日文字符 · ${x.questions.length} 道理解题 · ${state.completed[x.id]?'✓ 已读完':'未读完'}</p><div class="row">${btn('阅读','detail',x.id)}${btn('开始作答 →','reading-quiz',x.id,'primary')}</div>${actions(x)}</article>`).join('')}</div>${list.length?pager(list.length):empty()}`;}
function writing(){const w=W.find(x=>x.id===writingId)||W[0];return heading('WRITING DESK','让想法变成日语','分级写作、草稿自动保存与自检清单。检测只提供形式提示；自由作文不进行虚假的语义自动评分。')+`<div class="toolbar"><select id="writing-select" aria-label="写作任务">${W.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${x.level} · ${E(x.title)}</option>`).join('')}</select>${btn('导出这篇作文','export-draft',w.id)}</div><div class="panel">${badge(w.level)}<h2 class="jp">${E(w.title)}</h2><p>${E(w.prompt)}</p>${w.outline?`<p class="note">写作路径：${E(w.outline)}</p>`:''}<div class="note">目标表达：${w.targets.map(E).join(' ／ ')}。示范是短段落结构示意，不是按目标字数完成的整篇范文。</div><label for="draft" style="margin-top:20px">你的草稿</label><textarea id="draft" style="min-height:360px" data-id="${w.id}" lang="ja" placeholder="ここに書いてください…">${E(state.drafts[w.id]||'')}</textarea><div id="draft-analysis" class="small muted">${draftAnalysis(state.drafts[w.id]||'',w)}</div><details><summary>短段落示范 · 建议写完再看</summary><p class="jp">${E(w.sample)}</p></details><details><summary>提交前自检</summary><ul class="checklist"><li>有没有回答任务？观点和例子是否对应？</li><li>时态、助词、自动词与他动词是否一致？</li><li>敬体与简体是否在同一叙述层面保持一致？</li><li>授受与敬语视点是否适合说话者和对象？</li><li>有没有过度概括、重复或缺失的逻辑连接？</li><li>目标语法是否自然，而不是为了复杂而硬塞？</li></ul></details>${btn(state.completed[w.id]?'✓ 已完成（可取消）':'标记已完成自检','complete',w.id)}</div>`;}
function draftAnalysis(s,w){const len=[...s.replace(/\s/g,'')].length,paras=s.split(/\n+/).filter(x=>x.trim()).length;return `${len} 字符（不计空白） · ${paras} 段 · 目标表达字面出现：${w.targets.map(t=>`${E(t)} ${s.includes(t)?'✓':'—'}`).join(' / ')}。字面匹配无法识别所有活用形式，也不能判定用法是否正确。`;}
const MODES=[['meaning','词义选择','日文 → 中文，结合释义识别'],['reading','假名输入','看词写读音，使用日语输入法'],['reverse','词形识别','中文 → 对应日文词汇'],['grammar','句型理解','根据中文含义识别表达'],['connect','接续辨析','选择句型的规范接续'],['blank','语法填空','在完整例句中补出指定成分'],['order','句子排序','点击词块，重建目标句'],['translation','翻译重构','看中文输入目标日文句'],['conj','活用输入','五段、一段和不规则活用'],['kanji','汉字读音','选择该字的一项常见音读'],['kana','假名识读','平假名、片假名与罗马字'],['flash','闪卡自测','先回忆，再翻面并自评'],['usage','语境辨析','人工选项与解析，比较具体用法'],['mixed','综合练习','词汇、语法、活用与阅读混合'],['exam','限时综合','30分钟、40题，学习诊断分']];
function practice(){if(quiz)return quizView();return heading('PRACTICE CENTER','把“知道”练成“会用”','选择等级与题型，即时解析并记录错题。自动组题来自已有词条和人工编写的题目，重复抽样不计作新增知识点。')+`<div class="panel"><div class="toolbar"><label>训练级别 <select id="practice-level">${['全部','N5','N4','N3','N2','N1'].map(l=>`<option ${l===state.profile.level?'selected':''}>${l}</option>`).join('')}</select></label><label>每组题数 <select id="practice-count">${[10,20,30,50].map(n=>`<option ${n===20?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="note">输入题要求显示的标准目标；可能存在合理的其他表达，请按“查看标准答案”核对。翻译重构训练是记忆标准句，不是自由翻译自动评分。限时综合不是官方模拟卷，也不能换算JLPT合格分。</div></div><div class="grid3">${MODES.map(([m,t,s],i)=>`<article class="card"><span class="small muted">TRAINING ${String(i+1).padStart(2,'0')}</span><h2 style="margin-top:14px">${t}</h2><p>${s}</p>${btn('开始训练 ↗','start',m,'primary')}</article>`).join('')}</div>`;}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function norm(s){return s.normalize('NFKC').replace(/[\s。．.!！?？、，,]/g,'').trim();}
function kanaNorm(s){return norm(s).replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));}
function answers(s){return s.split(/[／/,、；;]/).map(x=>x.replace(/（[^）]*）|\([^)]*\)/g,'').trim()).filter(Boolean);}
function makeChoice(id,prompt,answer,distractors,why,extra={}){const options=shuffle([answer,...shuffle([...new Set(distractors.filter(x=>x&&x!==answer))]).slice(0,3)]);return {id,prompt,answer,options,why,type:'choice',...extra};}
function fromItem(x,mode){
 if(x?.conj)return conjQuestion(x);
 if(x?.readingQuestion)return {id:x.id,type:'choice',prompt:x.q,answer:x.options[x.answer],options:shuffle(x.options),why:x.why,text:x.text,translation:x.translation};
 if(x?.question&&x.options){return {id:x.id,type:'choice',prompt:x.question,answer:x.options[x.answer],options:shuffle(x.options),why:x.why};}
 if(x?.paragraphs&&x.level!=='入门'){const q=U.find(u=>u.topic===x.id);return q?fromItem(q,'usage'):null;}
 if(x.word){const pool=V.filter(v=>v.level===x.level&&v.id!==x.id);if(mode==='reading')return{id:x.id,type:'input',prompt:`写出「${x.word}」的假名读音`,answer:x.reading,accept:answers(x.reading),kana:true,why:x.meaning+'；词库读音：'+x.reading,extra:x.word};if(mode==='reverse')return makeChoice(x.id,x.meaning,x.word,pool.map(v=>v.word),`${x.word}（${x.reading}）：${x.meaning}`);if(mode==='flash')return{id:x.id,type:'flash',prompt:x.word,answer:`${x.reading} · ${x.meaning}`,why:x.examples[0]?.join(' — ')||x.pos};return makeChoice(x.id,x.word,x.meaning,pool.map(v=>v.meaning),`${x.word}（${x.reading}）：${x.meaning}`,{sub:x.pos});}
 if(x.pattern){const pool=G.filter(v=>v.level===x.level&&v.id!==x.id);if(mode==='connect')return makeChoice(x.id,'「'+x.pattern+'」的接续是？',x.connect,pool.map(v=>v.connect),x.note+' 例：'+x.example);return makeChoice(x.id,x.meaning,x.pattern,pool.map(v=>v.pattern),x.connect+'。'+x.note+' 例：'+x.example);}
 if(x.char){if(!x.on.length)return null;return makeChoice(x.id,'「'+x.char+'」的一项常见音读是？',x.on[0],K.filter(v=>!v.on.some(r=>x.on.includes(r))).map(v=>v.on[0]),'音读：'+x.on.join(' / ')+'；训读：'+x.kun.join(' / '));}
 if(x.sentence)return{id:x.id,type:'input',prompt:x.sentence,answer:x.answer,why:x.why+' '+x.zh};
 if(x.tokens)return{id:x.id,type:mode==='translation'?'input':'order',prompt:x.zh,answer:x.tokens.join(''),tokens:x.tokens,why:'目标句：'+x.tokens.join('')+'。本题只核对目标句，其他自然表达请人工对照。'};
 if(x.text){const q=pick(x.questions);return{id:mode==='legacy-review'?x.id:'rq:'+x.id+':'+x.questions.indexOf(q),type:'choice',prompt:q.q,answer:q.options[q.answer],options:shuffle(q.options),why:q.why,text:x.text,translation:x.translation};}
 if(x.rom){const which=pick(['h','k']);return makeChoice(x.id,'「'+x[which]+'」的罗马字是？',x.rom,KANA.map(v=>v.rom),'平假名 '+x.h+'；片假名 '+x.k+'；罗马字 '+x.rom);}
 return null;
}
function conjQuestion(item=pick(CONJ_ITEMS)){const w=item.wordBase,t=item.verbType,reading=item.kanaBase,form=item.form,a=conjugate(w,t)[form];return{id:item.id,type:'input',prompt:`${w}（${reading}）· ${t} → ${form}`,answer:a,accept:[a,conjugate(reading,t)[form]],why:`规范完整式：${a}。${t==='五段'?'注意变段与て／た形音便。':t==='一段'?'一段以去る后的词干为基础。':'不规则动词需单记。'}`,form};}
function buildQuestions(mode,level,count,ids=null){let list=[];const lv=a=>a.filter(x=>level==='全部'||x.level===level);
 if(ids){return ids.filter(id=>MAP.has(id)).slice(0,count).map(id=>{const x=MAP.get(id);if(mode==='wrong'&&state.wrong[id]?.question)return {...state.wrong[id].question,options:state.wrong[id].question.options?shuffle(state.wrong[id].question.options):undefined};if(mode==='word-flash')return fromItem(x,'flash');if(mode==='word-reading')return fromItem(x,'reading');return x?.id==='f6'?{...conjQuestion(),id:x.id}:x?.paragraphs&&x.level==='入门'?fromItem(pick(KANA),'kana'):fromItem(x,'legacy-review');}).filter(Boolean);}
 if(mode==='usage')return shuffle(lv(U)).slice(0,count).map(x=>fromItem(x,mode));
 if(mode==='conj')return Array.from({length:count},conjQuestion);
 if(mode==='mixed'||mode==='exam'){const pools=[...lv(V).map(x=>[x,pick(['meaning','reading','reverse'])]),...lv(G).map(x=>[x,'grammar']),...lv(B).map(x=>[x,'blank']),...lv(O).map(x=>[x,'order'])];const a=shuffle(lv(V)).slice(0,Math.ceil(count*.35)).map(x=>fromItem(x,pick(['meaning','reading','reverse']))),g=shuffle([...lv(G),...lv(U)]).slice(0,Math.ceil(count*.25)).map(x=>fromItem(x,x.question?'usage':'grammar')),b=shuffle(lv(B)).slice(0,Math.ceil(count*.15)).map(x=>fromItem(x,'blank')),o=shuffle(lv(O)).slice(0,Math.ceil(count*.1)).map(x=>fromItem(x,'order')),r=shuffle(lv(R)).slice(0,2).map(x=>fromItem(x));list=[...a,...g,...b,...o,...r];while(list.length<count)list.push(conjQuestion());return shuffle(list).slice(0,count);}
 if(['meaning','reading','reverse','flash'].includes(mode))list=lv(V);else if(['grammar','connect'].includes(mode))list=lv(G);else if(mode==='blank')list=lv(B);else if(['order','translation'].includes(mode))list=lv(O);else if(mode==='kanji')list=lv(K).filter(x=>x.on.length);else if(mode==='kana')list=KANA.filter(x=>x.group===kanaGroup);
 return shuffle(list).slice(0,count).map(x=>fromItem(x,mode)).filter(Boolean);
}
function startQuiz(mode,level='全部',count=20,ids=null){clearInterval(sessionTimer);const questions=buildQuestions(mode,level,count,ids);if(!questions.length){toast('这个范围还没有适合的题，请调整级别或题型。');return;}quiz={mode,level,questions,index:0,ok:0,answers:[],answered:false,start:Date.now(),limit:mode==='exam'?30*60:0,flipped:false,selected:[],tokens:null};if($('#detail').open)$('#detail').close();if(location.hash!=='#practice'){location.hash='practice';}else render();if(quiz.limit)sessionTimer=setInterval(tick,1000);}
function tick(){if(!quiz?.limit)return;const left=Math.max(0,quiz.limit-Math.floor((Date.now()-quiz.start)/1000));const el=$('#timer');if(el)el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(!left){clearInterval(sessionTimer);quiz.finished=true;render();}}
function quizView(){const qz=quiz;if(qz.finished||qz.index>=qz.questions.length)return results();const q=qz.questions[qz.index];if(!qz.tokens&&q.type==='order')qz.tokens=shuffle(q.tokens.map((t,i)=>({t,i})));const modeTitle=MODES.find(x=>x[0]===qz.mode)?.[1]||({'reading-text':'阅读理解',due:'到期复习',wrong:'错题再练','word-flash':'单词本闪卡','word-reading':'单词本读音输入'}[qz.mode]||'复习');return `<div class="quiz-wrap">${heading('FOCUSED PRACTICE',modeTitle,`${qz.level} · 第 ${qz.index+1} / ${qz.questions.length} 题`,btn('结束这组','end-quiz','','subtle'))}<div class="row between small muted"><span>已答对 ${qz.ok} 题</span><span id="timer">${qz.limit?'30:00':'不计时 · 从容思考'}</span></div><div class="bar" style="margin:12px 0 25px"><i style="width:${qz.index/qz.questions.length*100}%"></i></div><section class="panel quiz-main">${q.text?`<div class="reading-text">${JP(q.text)}</div>`:''}<div class="quiz-question ${q.type==='flash'?'flash jp':''}">${q.type==='input'||q.type==='flash'||(MAP.get(q.id)?.char)?E(q.prompt):JP(q.prompt,MAP.get(q.id)?.word===q.prompt?MAP.get(q.id).reading:undefined)}</div>${q.sub?`<p class="small muted">${E(q.sub)}</p>`:''}${q.type==='choice'?`<div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${qz.answered?(o===q.answer?'correct':qz.given===o?'wrong':''):''}" data-act="answer-choice" data-id="${i}" ${qz.answered?'disabled':''}><span class="muted">${i+1}.</span> ${MAP.get(q.id)?.char?E(o):JP(o)}</button>`).join('')}</div>`:q.type==='flash'?qz.flipped?`<div class="flash-back">${E(q.answer)}</div><p class="small muted">${E(q.why)}</p><div class="row" style="justify-content:center">${btn('没记住 · 稍后再见','flash-grade','0')}${btn('记住了','flash-grade','1','primary')}${btn('很熟练','flash-grade','2')}</div>`:btn('想好后翻面 ↻','flip','','primary'):q.type==='order'?`<div class="tokens" aria-label="已排序词块">${qz.selected.map((idx,i)=>btn(E(q.tokens[idx]),'untoken',i,'token')).join('')||'<span class="muted small">按顺序点击下方词块</span>'}</div><div class="tokens" aria-label="可选词块">${qz.tokens.filter(x=>!qz.selected.includes(x.i)).map(x=>btn(E(x.t),'token',x.i,'token')).join('')}</div>${!qz.answered?`<div class="row" style="margin-top:22px;justify-content:center">${btn('检查顺序','submit-order','','primary')}${btn('重置词块','reset-order')}</div>`:''}`:`<div class="quiz-answer"><input id="quiz-input" autocomplete="off" lang="ja" aria-label="输入答案" placeholder="使用日语输入法输入…" ${qz.answered?'disabled':''} value="${E(qz.given||'')}">${!qz.answered?btn('检查答案','submit-input','','primary'):''}</div>`}${!qz.answered&&q.type!=='flash'?`<div style="margin-top:16px">${btn('查看标准答案（记为未掌握）','reveal','','text-btn small muted')}</div>`:''}${qz.answered?`<div class="quiz-feedback"><strong style="color:var(--${qz.lastOK?'good':'red'})">${qz.lastOK?'✓ 回答正确':'需要再看一次'}</strong>${qz.given?`<p>你的答案：${E(qz.given)}</p>`:''}<p>标准答案：<span class="jp">${JP(q.answer)}</span></p><p class="muted">${E(q.why)}</p>${q.translation?`<details><summary>中文对照</summary>${E(q.translation)}</details>`:''}<div class="row">${btn(qz.index+1===qz.questions.length?'查看本组报告 →':'下一题 →','next','','primary')}${btn('查看知识卡','detail',q.id)}${btn(state.stars[q.id]?'★ 已收藏':'☆ 收藏','quiz-star',q.id)}</div></div>`:''}</section><div class="note">选择题可按 1–4；输入完成按 Enter 检查，解析后按 Enter 下一题。输入法选词时不会触发提交。${q.type==='input'?'忽略空白、常见标点和全半角差异；读音题也兼容片假名。':''}</div></div>`;}
function record(id,ok,rating=1){const now=Date.now(),r=state.reviews[id]||{due:now,interval:0,ease:2.5,seen:0,correct:0};r.seen++;if(ok){r.correct++;r.interval=r.interval===0?1:r.interval===1?3:Math.min(365,r.interval*r.ease*(rating===2?1.3:1));r.ease=Math.min(3.2,r.ease+(rating===2?.1:0));r.due=now+r.interval*864e5;delete state.wrong[id];}else{r.interval=0;r.ease=Math.max(1.3,r.ease-.2);r.due=now+10*60e3;state.wrong[id]={count:(state.wrong[id]?.count||0)+1,last:now};if(quiz?.questions[quiz.index]?.id===id){state.wrong[id].question=JSON.parse(JSON.stringify(quiz.questions[quiz.index]));state.wrong[id].given=quiz.given||'';}}state.reviews[id]=r;SYNC.addAttempt(state,id,ok,now,quiz?.mode||'练习',today());SYNC.stamp(state,'reviews',id);SYNC.stamp(state,'wrong',id);save();}
function submit(given,reveal=false,rating=1){if(!quiz||quiz.answered)return;const q=quiz.questions[quiz.index];const correct=q.type==='flash'?rating>0:!reveal&&(q.accept||[q.answer]).some(a=>(q.kana?kanaNorm(a):norm(a))===(q.kana?kanaNorm(given):norm(given)));quiz.answered=true;quiz.given=given;quiz.lastOK=correct;if(correct)quiz.ok++;quiz.answers.push({q,given,ok:correct});record(q.id,correct,rating);render();}
function results(){clearInterval(sessionTimer);const n=quiz.answers.length,total=quiz.questions.length,elapsed=Math.floor((Date.now()-quiz.start)/1000);return `<div class="quiz-wrap">${heading('SESSION COMPLETE','每次练习，都有收获。','这是本次学习诊断，不对应官方考试分数。未作答题不计入记忆日程；限时模式下计入整组得分分母。')}<div class="stats"><div class="stat"><small>诊断正确率</small><strong>${Math.round(quiz.ok/total*100)}%</strong></div><div class="stat"><small>已作答</small><strong>${n}/${total}</strong></div><div class="stat"><small>答对</small><strong>${quiz.ok}</strong></div><div class="stat"><small>用时</small><strong>${Math.floor(elapsed/60)}<span class="unit">分 ${elapsed%60} 秒</span></strong></div></div><div class="row" style="margin-bottom:28px">${btn('重新练习本组','retry','','primary')}${btn('返回训练中心','leave-quiz')}${btn('去错题本','quiz-review')}</div>${quiz.answers.map(({q,given,ok})=>`<div class="panel"><div class="small ${ok?'learned':'gold'}">${ok?'✓ 正确':'↻ 需复习'}</div><h3>${E(q.prompt)}</h3><p>你的答案：${E(given||'（查看了答案）')}<br>标准答案：${E(q.answer)}</p><p class="muted">${E(q.why)}</p>${btn('查看知识卡','detail',q.id)}</div>`).join('')}</div>`;}
function canReview(x){return !!(x&&(x.word||x.id==='f6'||x.pattern||x.char&&x.on.length||x.readingQuestion||x.text||x.sentence||x.tokens||x.conj||x.rom||x.question));}
function scheduleIds(ids){let n=0;for(const id of ids){if(!canReview(MAP.get(id)))continue;const old=state.reviews[id];state.reviews[id]=old?{...old,due:Math.min(old.due,Date.now())}:{due:Date.now(),interval:0,ease:2.5,seen:0,correct:0};SYNC.stamp(state,'reviews',id);n++;}save();return n;}
function bookItems(){let list=V.filter(x=>bookView==='收藏单词'?state.stars[x.id]:bookView==='已练单词'?state.reviews[x.id]?.seen>0:state.wordbook[x.id]);if(bookView==='待复习')list=list.filter(x=>state.reviews[x.id]?.due<=Date.now());if(bookView==='未掌握')list=list.filter(x=>!state.learned[x.id]);if(bookView==='已掌握')list=list.filter(x=>state.learned[x.id]);return list.filter(x=>(filterLevel==='全部'||x.level===filterLevel)&&(!search||[x.word,x.reading,x.meaning,state.notes[x.id]||''].join(' ').toLowerCase().includes(search.toLowerCase())));}
function wordbook(){const list=bookItems();page=Math.min(page,Math.max(1,Math.ceil(list.length/24)));const visible=list.slice((page-1)*24,page*24);return heading('MY WORDS','单词本','单词本单独收录你想学的词；收藏和既有练习仍保留，可从对应标签批量加入。筛选后选词，安排复习或开始自测。')+chips(['N5','N4','N3','N2','N1'])+`<div class="chips">${['全部','未掌握','已掌握','待复习','收藏单词','已练单词'].map(t=>btn(t,'book-view',t,'chip '+(bookView===t?'active':''))).join('')}</div>`+toolbar('搜索单词、读音、中文或笔记…',false)+`<section class="panel collection-tools"><p>单词本 ${V.filter(x=>state.wordbook[x.id]).length} 词 · 收藏 ${V.filter(x=>state.stars[x.id]).length} 词 · 本次已选 <span id="selection-count">${selectedWords.size}</span> 词</p><div class="row">${btn('选择本页','book-select-page')}${btn('取消选择','book-unselect')}${btn('选词加入单词本','book-add')}${btn('选词加入今日复习','book-schedule')}${btn('选词闪卡自测','book-flash','','primary')}${btn('选词读音输入','book-reading')}${btn('从单词本移除选词','book-remove')}${btn('导出当前筛选TSV','book-export')}${btn(state.profile.ruby?'注音：开':'注音：关','ruby')}</div><p class="small muted">移出单词本不会删除收藏、笔记或复习记录。加入今日复习不计作答，也不重置原有熟悉度。TSV为阅读清单；完整进度同步请使用存档JSON。</p></section><div class="grid3">${visible.map(x=>{const r=state.reviews[x.id];return `<article class="card"><div class="row between">${badge(x.level)}<label class="word-check"><input type="checkbox" class="word-select" data-id="${x.id}" ${selectedWords.has(x.id)?'checked':''} aria-label="选择${E(x.word)}">选择</label></div><div class="word-card-head"><div><h2 class="jp">${JP(x.word,x.reading)}</h2><p>${E(x.meaning)}</p></div>${wordImage(x,true)}</div><p class="small muted">${r?'复习 '+new Date(r.due).toLocaleDateString()+' · 已练 '+r.seen+' 次':'尚未安排复习'}</p>${state.notes[x.id]?`<p class="book-note">${E(state.notes[x.id].slice(0,180))}</p>`:''}${actions(x)}</article>`;}).join('')}</div>${list.length?pager(list.length):empty('当前筛选没有单词。先去词汇页加入，或从收藏单词标签选择。')}`;}
function exportWordbook(){const rows=[['词语','平假名','中文释义','等级','笔记','已掌握','下次复习'],...bookItems().map(x=>[x.word,x.reading,x.meaning,x.level,state.notes[x.id]||'',state.learned[x.id]?'是':'否',state.reviews[x.id]?new Date(state.reviews[x.id].due).toISOString():''])];const cell=x=>{const t=String(x).replace(/[\t\r\n]/g,' ');return /^[=+@-]/.test(t)?"'"+t:t;};download('kotobapath-wordbook-'+today()+'.tsv','\ufeff'+rows.map(r=>r.map(cell).join('\t')).join('\n'),'text/tab-separated-values;charset=utf-8');}
function reviewCategory(x){return x.word?'词汇':x.readingQuestion||x.text?'阅读':x.pattern||x.question||x.paragraphs?'语法':x.char?'汉字':x.conj?'活用':x.rom?'假名':'句子';}
function reviewItems(view=reviewView){const recent=new Map();if(reviewSort==='recent')for(const h of state.history)recent.set(h.id,Math.max(recent.get(h.id)||0,h.time));let ids=(view==='错题'?Object.keys(state.wrong):view==='到期'?dueIds():view==='全部计划'?Object.keys(state.reviews):[...new Set(state.history.filter(h=>!h.ok).map(h=>h.id))]).filter(id=>canReview(MAP.get(id)));ids=ids.filter(id=>{const x=MAP.get(id);return (filterLevel==='全部'||x.level===filterLevel)&&(reviewKind==='全部'||reviewCategory(x)===reviewKind)&&(!search||[itemTitle(x),x.q||'',x.reading||'',x.meaning||''].join(' ').toLowerCase().includes(search.toLowerCase()));});return ids.sort((a,b)=>reviewSort==='errors'?(state.wrong[b]?.count||0)-(state.wrong[a]?.count||0):reviewSort==='recent'?(state.wrong[b]?.last||(recent.get(b)||0))-(state.wrong[a]?.last||(recent.get(a)||0)):(state.reviews[a]?.due||0)-(state.reviews[b]?.due||0));}
function review(){const ids=reviewItems(),next=Object.entries(state.reviews).filter(([id,r])=>canReview(MAP.get(id))&&r.due>Date.now()).sort((a,b)=>a[1].due-b[1].due)[0];page=Math.min(page,Math.max(1,Math.ceil(ids.length/24)));return heading('MEMORY GARDEN','复习与错题本','错题保留本次题型、选项和你的答案；答对移出当前错题，历史仍可回看。答错约10分钟后再练，答对按1天、3天及熟悉度延长。')+`<div class="stats"><div class="stat"><small>已到期</small><strong>${dueIds().length}</strong></div><div class="stat"><small>当前错题</small><strong>${Object.keys(state.wrong).filter(id=>canReview(MAP.get(id))).length}</strong></div><div class="stat"><small>复习计划</small><strong>${Object.keys(state.reviews).filter(id=>canReview(MAP.get(id))).length}</strong></div><div class="stat"><small>下次到期</small><p>${next?E(new Date(next[1].due).toLocaleString()):'暂无未来计划'}</p></div></div>`+chips(['N5','N4','N3','N2','N1'])+`<div class="chips">${['错题','到期','全部计划','历史错题'].map(t=>btn(t,'review-view',t,'chip '+(reviewView===t?'active':''))).join('')}</div>`+toolbar('搜索题目、知识标题或读音…',false)+`<div class="toolbar"><label>内容<select id="review-kind">${['全部','词汇','语法','阅读','汉字','活用','假名','句子'].map(t=>`<option ${reviewKind===t?'selected':''}>${t}</option>`).join('')}</select></label><label>排序<select id="review-sort">${[['due','最早到期'],['recent','最近出错／作答'],['errors','错误次数']].map(([v,t])=>`<option value="${v}" ${v===reviewSort?'selected':''}>${t}</option>`).join('')}</select></label><label>每组题数<select id="review-count">${[10,20,30,50,100].map(n=>`<option ${n===reviewCount?'selected':''}>${n}</option>`).join('')}</select></label>${btn('复习筛选内到期项','review-due','','primary')}${btn('重练筛选内错题','review-wrong')}</div><p class="note">到期项按所选排序依次练习，未抽到的仍在计划中。历史错题限最近5000次保留记录；手动移出错题不会删除复习计划。旧存档没有原题快照的条目仍按知识点生成复习题。此为简化间隔复习，不是FSRS。</p><div class="section-head"><h2>${E(reviewView)} · ${ids.length} 项</h2></div>${ids.slice((page-1)*24,page*24).map(id=>{const x=MAP.get(id),w=state.wrong[id],r=state.reviews[id];return `<article class="panel"><div class="row between">${badge(x.level)}<span class="small muted">${E(reviewCategory(x))}${w?' · 当前累计错误 '+w.count+' 次':''}</span></div><h3>${x.word?JP(x.word,x.reading):E(itemTitle(x))}</h3>${w?.question?`<p>${JP(w.question.prompt)}</p><details><summary>上次答案与标准答案</summary><p>你的答案：${E(w.given||'未作答／查看答案')}</p><p>标准答案：${JP(w.question.answer)}</p><p>${E(w.question.why)}</p></details>`:''}<p class="small muted">${r?'到期 '+new Date(r.due).toLocaleString()+' · 间隔 '+Number(r.interval.toFixed(1))+' 天 · 正确 '+r.correct+'/'+r.seen:'尚无日程'}</p><div class="row">${btn('重练这一项','review-one',id,'primary')}${btn('查看知识卡与解析','detail',id)}${btn('加入今日复习','schedule',id)}${w?btn('移出当前错题','wrong-clear',id):''}</div></article>`;}).join('')}${ids.length?pager(ids.length):empty('此筛选暂时没有条目。可从单词本加入计划，或先完成训练。')}`;}
function itemTitle(x){return (x?.conj?x.wordBase+' → '+x.form:'')||x?.word||x?.pattern||x?.char||x?.title||x?.sentence||x?.question||(x?.readingQuestion?itemTitle(MAP.get(x.article))+' · 理解题':'')||x?.zh||x?.h||'知识卡';}
function notebook(){let ids=[...new Set([...Object.keys(state.stars),...Object.keys(state.notes).filter(id=>state.notes[id].trim())])].filter(id=>MAP.has(id)&&(!search|| (itemTitle(MAP.get(id))+' '+(state.notes[id]||'')).includes(search)));return heading('PERSONAL COLLECTION','你的词句，随手收藏','收藏跨词汇、语法、汉字与阅读。笔记在知识卡里编辑，所有内容随存档一起迁移。')+toolbar('搜索收藏标题或我的笔记…',false)+`<div class="grid3">${ids.map(id=>{const x=MAP.get(id);return `<article class="card">${badge(x.level)}<h3 style="margin-top:14px">${x.word?JP(x.word,x.reading):E(itemTitle(x))}</h3><p style="white-space:pre-wrap">${E((state.notes[id]||'还没有笔记，打开知识卡记录自己的理解。').slice(0,200))}</p>${actions(x)}</article>`;}).join('')}</div>${ids.length?'':empty('还没有收藏和笔记。打开一张知识卡，点击 ☆ 即可收藏。')}`;}
function stats(){const n=Object.values(state.days).reduce((a,x)=>a+x.total,0),c=Object.values(state.days).reduce((a,x)=>a+x.correct,0);return heading('LEARNING INSIGHTS','看见自己的积累','统计基于本机作答记录。掌握标记是自评，不代表已经达到对应考试等级。')+`<div class="stats"><div class="stat"><small>累计作答</small><strong>${n}</strong></div><div class="stat"><small>累计正确率</small><strong>${n?Math.round(c/n*100):0}%</strong></div><div class="stat"><small>学习天数</small><strong>${Object.keys(state.days).filter(d=>state.days[d].total>0).length}</strong></div><div class="stat"><small>课文已读完</small><strong>${[...F,...G].filter(x=>state.completed[x.id]).length}</strong></div></div><div class="grid2"><div class="panel"><h2>近七天训练</h2>${weekChart()}</div><div class="panel"><h2>词汇掌握分布</h2>${LEVELS.slice(1).map(l=>{const a=V.filter(x=>x.level===l),done=a.filter(x=>state.learned[x.id]).length;return `<div class="mini-chart"><label>${l}</label><div class="bar"><i style="width:${done/a.length*100}%"></i></div><span class="small muted">${done}/${a.length}</span></div>`;}).join('')}</div></div><div class="panel"><h2>近期训练记录</h2><div class="scroll"><table><thead><tr><th>时间</th><th>知识</th><th>结果</th></tr></thead><tbody>${state.history.slice(-30).reverse().map(x=>`<tr><td class="small">${new Date(x.time).toLocaleString()}</td><td>${E(itemTitle(MAP.get(x.id)))}</td><td>${x.ok?'✓ 正确':'↻ 复习'}</td></tr>`).join('')}</tbody></table></div>${n?'':empty('完成训练后将在这里显示记录。')}</div>`;}
function settings(){return heading('MAKE IT YOURS','按自己的节奏学习','存档只保存在当前浏览器，清除站点数据会删除进度。建议定期导出JSON备份；跨设备请手动导入。')+`${storageProblem?`<div class="note notice">${E(storageProblem)} ${btn('导出原始本机存档','export-raw')}${btn('保留原始备份后启用当前进度','resolve-storage')}</div>`:''}<div class="panel"><h2>学习偏好</h2><div class="toolbar"><label>当前路线<select id="pref-level">${LEVELS.map(l=>`<option ${state.profile.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>每日作答目标<select id="pref-daily">${[10,20,30,50,100].map(x=>`<option ${state.profile.daily===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="font-control"><label>字体大小</label><input id="pref-font" type="range" min="18" max="24" value="${state.profile.font}" aria-label="字体大小"><span>${state.profile.font}px</span></div><div class="row" style="margin-top:20px">${btn(state.profile.ruby?'✓ 汉字上方注音：开启':'汉字上方注音：关闭','ruby')}${btn(state.profile.light?'切换深色':'切换亮色','theme')}</div><p class="small muted" style="margin-top:20px">注音覆盖词条、例句与阅读正文；读音输入、汉字识读及闪卡正面不显示提示，避免泄露答案。多音字注音为词法分析结果，生僻词和专名可对照词卡核实。中文说明不加注。系统日语字体决定字形；不加载CDN或网络字体。最低正文字号18px，最高24px。</p></div><div class="panel"><h2>存档迁移</h2><p>导出包含进度、复习日程、错题、收藏、笔记与作文草稿。导入前会先校验并展示概要，可合并同步或完整替换，并提供当前进度备份。1.0旧存档可直接升级。</p><div class="row">${btn('↗ 导出存档JSON','export','','primary')}${btn('↙ 导入存档JSON','import')}${btn('导出学习摘要','export-summary')}${btn('导出升级前原始备份','export-upgrade-backup')}${btn('导出冲突文本副本','export-conflicts')}</div><h3 style="margin-top:24px">文本冲突副本（${state.sync.conflicts.length}）</h3><p class="small muted">同一笔记或作文在两端不同，保留非主版本供人工合并；不会把两段作文直接拼接成一篇。</p>${state.sync.conflicts.slice(-20).map(x=>`<details><summary>${E(x.field==='drafts'?'作文':'笔记')} · ${E(itemTitle(MAP.get(x.id))||x.id)}</summary><pre style="white-space:pre-wrap">${E(x.value)}</pre></details>`).join('')}</div><div class="panel"><h2>重置进度</h2><p class="muted">需在确认框中输入 RESET。重置前会自动提供备份下载。</p>${btn('重置学习数据','reset-prompt','','danger')}</div>`;}
function about(){return heading('ABOUT KOTOBAPATH','言葉の道','纯HTML、CSS和原生JavaScript；无账户、无音频、无外部请求、不含统计追踪。')+`<div class="panel prose"><h2>当前收录与边界</h2><div class="scroll"><table><tr><th>内容</th><th>实际数量与说明</th></tr><tr><td>分级词汇</td><td>${V.length} 个中文释义词条，含读音与词性</td></tr><tr><td>原创词汇例句</td><td>${V.reduce((n,w)=>n+w.examples.length,0)} 条，附中文对照</td></tr><tr><td>词汇配图</td><td>${WORD_VISUALS.size} 张独立绘制的原创 SVG</td></tr><tr><td>语法讲解</td><td>${G.length} 项接续、例句、翻译和易错提示</td></tr><tr><td>汉字</td><td>${K.length} 字；音训、笔画、${K.filter(k=>k.meaningZh).length}字中文释义、英文参考与中文关联词</td></tr><tr><td>辨析专题</td><td>${T.length}课，含成对例句和语境练习</td></tr><tr><td>人工语境题</td><td>${U.length}道，使用人工设定选项与解析</td></tr><tr><td>基础专题</td><td>${F.length} 课，涵盖文字、活用、助词、敬语、阅读和写作方法</td></tr><tr><td>原创阅读</td><td>${R.length} 篇，共${R.reduce((n,x)=>n+x.questions.length,0)}题，含长篇论说、信息检索与多文本比较</td></tr><tr><td>固定句子题</td><td>${B.length} 道填空、${O.length} 道排序／翻译重构</td></tr><tr><td>写作任务</td><td>${W.length} 个；提供短段落示意与形式自检，无法自动判断自然度</td></tr></table></div><p>本项目不是对“所有日语知识点”的穷尽收录。JLPT不发布现行完整词汇、汉字和语法清单，各级标签是学习参考。当前收录量以本页统计和覆盖清单为准；课程不应被视为从零到N1的完整认证教材，完成进度不应被解释为已达到N1。</p><p>未加入听力与口语。完整JLPT包含听力，单凭本网站的训练不能保证通过N1。应结合更广泛的阅读、分级测验与后续听力学习检验能力。</p><h2>设计参考</h2><p>参考《げんき》公开教学框架中循序引入文字、基础结构与读写的方式，并采用从基础表达走向复杂语境的分级路线。未复制其课文、练习、插图或整套知识编排。本站中文讲解、语法例句、阅读和固定句题为另行编写。</p><p><a class="link" href="https://genki3.japantimes.co.jp/en/intro/index.html" target="_blank" rel="noopener">GENKI 官方介绍 ↗</a> · <a class="link" href="https://www.jlpt.jp/e/faq/" target="_blank" rel="noopener">JLPT 官方FAQ ↗</a></p><h2>来源与许可</h2><p>词汇配图及词汇例句由 KotobaPath 绘制和编写，按 CC BY 4.0 提供。<a class="link" href="licenses/WORD-VISUALS.md">词图与例句来源</a></p><p>代码：GPL-3.0-or-later。原创教学内容：CC BY 4.0。基础10641个词汇及其例句来自egg rolls的JLPT10k，CC BY-NC 4.0，只允许非商业使用；新增原创搭配与专题词汇采用CC BY 4.0。词条分级和释义可能有误，不能当作官方标准。</p><p>汉字数据：KANJIDIC2／EDRDG（CC BY-SA 4.0）与Jonathan Waller分级，经davidluzgouveia/kanji-data整理。未使用源数据的WaniKani字段。做了筛选、字段整理，未翻译英文释义。分发时保留对应署名及许可，不将第三方数据统一改为GPL。</p><p><a href="https://github.com/5mdld/anki-jlpt-decks" target="_blank" rel="noopener" class="link">egg rolls 词库 ↗</a> · <a href="https://github.com/davidluzgouveia/kanji-data" target="_blank" rel="noopener" class="link">kanji-data ↗</a> · <a href="licenses/NOTICE.md" target="_blank" class="link">完整来源说明 ↗</a></p></div>`;}
function render(){route=(location.hash.slice(1)||'home').split('?')[0];if(!NAV.some(x=>x[0]===route)&&route!=='about')route='home';$('#crumb').textContent=NAV.find(x=>x[0]===route)?.[2]||'关于与来源';$('#nav').innerHTML=NAV.map(([r,i,t],idx)=>`${idx===9?'<div class="divider"></div>':''}<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}><b>${i}</b>${t}</a>`).join('');const pages={home,courses,kana,topics,vocab:()=>library('vocab'),grammar:()=>library('grammar'),kanji:()=>library('kanji'),conjugation,reading,writing,practice,review,wordbook,notebook,stats,settings,about};$('#main').innerHTML=pages[route]();$$('.disabled-ui').forEach(x=>x.disabled=true);prefs();if(quiz&&route==='practice'&&quiz.limit)tick();}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportSave(){download('kotobapath-save-'+today()+'.json',JSON.stringify(state,null,2));toast('已生成存档下载，请保管备份文件。');}
function resetFilters(){selectedWords.clear();filterLevel='全部';search='';page=1;only='all';readingGenre='全部';readingStatus='全部';}
function toggle(field,id){if(!MAP.has(id))return;state[field][id]?delete state[field][id]:state[field][id]=true;SYNC.stamp(state,field,id);save();}
let pendingImport=null,pendingFilter=null;
function importSummary(candidate){
 const unknown=new Set(['learned','stars','completed','notes','drafts','reviews','wrong'].flatMap(f=>Object.keys(candidate[f]).filter(id=>!MAP.has(id))));
 return `<p>合并／替换后：掌握 ${Object.keys(candidate.learned).length} 项，收藏 ${Object.keys(candidate.stars).length} 项，笔记 ${Object.keys(candidate.notes).length} 项，作文 ${Object.keys(candidate.drafts).length} 篇。<br>保留冲突文本副本 ${candidate.sync.conflicts.length} 份，暂未识别但保留的条目 ${unknown.size} 项。</p>`;
}
function importCandidate(){return $('#import-mode')?.value==='replace'?pendingImport:SYNC.merge(state,pendingImport,$('#import-policy')?.value||'local');}
function refreshImportPreview(){try{$('#import-summary').innerHTML=importSummary(importCandidate());}catch(e){$('#import-summary').textContent='无法合并：'+e.message;}}
async function importFile(file){
 if(!file)return;if(file.size>12*1024*1024){toast('存档超过12MB，无法导入。');return;}
 try{pendingImport=validateSave(JSON.parse(await file.text()));
 $('#modal-body').innerHTML=`<h1>同步与导入预览</h1><p>旧版存档可直接导入。新增课程使用稳定ID，与旧进度并存。</p><label for="import-mode">导入方式</label><select id="import-mode"><option value="merge">合并进度（推荐）</option><option value="replace">完整替换为导入存档</option></select><label for="import-policy" style="margin-top:18px">没有可靠修改时间的冲突如何处理</label><select id="import-policy"><option value="local">优先本机，保留另一份文本</option><option value="imported">优先导入，保留另一份文本</option></select><div id="import-summary" class="note" style="margin-top:20px"></div><p class="small muted">新版本的修改按时间合并；不同笔记与草稿保留副本。1.0旧版无事件ID的日累计取两边较大值，无法还原两台设备独立作答的精确和。1.2后的作答按唯一事件ID去重合并。此操作为手动跨设备同步，无账号和云服务。</p><p class="note">确认前先下载当前进度备份。完整替换会移除本机独有进度，请先保管下载文件。</p>${btn('备份并应用','apply-import','','primary')}`;
 $('#detail').showModal();refreshImportPreview();
 }catch(e){pendingImport=null;toast('导入失败：'+e.message);}
}

document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;e.preventDefault();const a=el.dataset.act,id=el.dataset.id;
 switch(a){
 case'go':if($('#detail').open)$('#detail').close();location.hash=id;break;
 case'filter':filterLevel=id;page=1;render();break;
 case'page':page=Math.max(1,Number(id));render();window.scrollTo({top:80,behavior:'smooth'});break;
 case'detail':modal(MAP.get(id));break;
 case'learn':case'star':toggle(a==='learn'?'learned':'stars',id);render();break;
 case'book':toggle('wordbook',id);render();break;
 case'modal-book':toggle('wordbook',id);el.textContent=state.wordbook[id]?'册 已入单词本':'＋ 单词本';break;
 case'schedule':scheduleIds([id]);toast('已加入今日复习，不影响作答统计');if(!$('#detail').open)render();break;
 case'modal-star':case'modal-learn':toggle(a==='modal-star'?'stars':'learned',id);el.textContent=a==='modal-star'?(state.stars[id]?'★ 已收藏':'☆ 收藏'):(state.learned[id]?'✓ 已掌握':'标记掌握');break;
 case'quiz-star':toggle('stars',id);render();break;
 case'complete':toggle('completed',id);el.textContent=state.completed[id]?'✓ 已读完（可取消）':'标记课文已读完';if(!$('#detail').open)render();break;
 case'course-level':state.profile.level=id;SYNC.stamp(state,'profile','level');save();if(location.hash==='#courses'){filterLevel=id;render();}else{pendingFilter=id;location.hash='courses';}break;
 case'kana-group':kanaGroup=id;render();break;
 case'kana-kind':kanaKind=id;render();break;
 case'kana-quiz':startQuiz('kana','入门',20);break;
 case'conj-example':conjWord=id;conjType=CONJ_VERBS.find(x=>x[0]===id)[1];render();break;
 case'conj-render':conjWord=$('#conj-word').value.trim();conjType=$('#conj-type').value;if(!conjWord){toast('请输入辞书形');break;}$('#conj-output').innerHTML=conjTable();break;
 case'conj-quiz':startQuiz('conj','全部',20);break;
 case'topic-quiz':startQuiz('usage',MAP.get(id)?.level||'全部',20,U.filter(x=>x.topic===id).map(x=>x.id));break;
 case'grammar-quiz':startQuiz('usage',MAP.get(id).level,20,U.filter(x=>x.grammar===id).map(x=>x.id));break;
 case'level-practice':startQuiz('grammar',id,20);break;
 case'reading-quiz':{const x=MAP.get(id);startQuiz('reading-text',x.level,1,[id]);quiz.questions=RQ.filter(q=>q.article===x.id).map(q=>fromItem(q,'reading-text'));render();break;}
 case'start':startQuiz(id,$('#practice-level').value,id==='exam'?40:Number($('#practice-count').value));break;
 case'answer-choice':if(quiz&&!quiz.answered)submit(quiz.questions[quiz.index].options[Number(id)]);break;
 case'submit-input':{const t=$('#quiz-input');if(!t?.value.trim()){toast('先输入答案，或选择查看标准答案。');break;}submit(t.value);break;}
 case'reveal':submit('',true);break;
 case'flip':quiz.flipped=true;render();break;
 case'flash-grade':if(quiz&&!quiz.answered){submit('',false,Number(id));nextQ();}break;
 case'token':if(!quiz.answered){quiz.selected.push(Number(id));render();}break;
 case'untoken':if(!quiz.answered){quiz.selected.splice(Number(id),1);render();}break;
 case'reset-order':quiz.selected=[];render();break;
 case'submit-order':if(quiz.selected.length!==quiz.questions[quiz.index].tokens.length){toast('请先使用全部词块。');break;}submit(quiz.selected.map(i=>quiz.questions[quiz.index].tokens[i]).join(''));break;
 case'next':nextQ();break;
 case'end-quiz':quiz.finished=true;render();break;
 case'retry':{const qs=quiz.questions.map(q=>({...q,options:q.options?shuffle(q.options):undefined})),mode=quiz.mode,level=quiz.level;clearInterval(sessionTimer);quiz={mode,level,questions:shuffle(qs),index:0,ok:0,answers:[],answered:false,start:Date.now(),limit:mode==='exam'?1800:0,flipped:false,selected:[],tokens:null};if(quiz.limit)sessionTimer=setInterval(tick,1000);render();break;}
 case'leave-quiz':clearInterval(sessionTimer);quiz=null;render();break;
 case'quiz-review':clearInterval(sessionTimer);quiz=null;location.hash='review';break;
 case'review-due':{const ids=reviewItems('到期');if(!ids.length){toast('当前筛选没有到期条目');break;}startQuiz('due',filterLevel,reviewCount,ids);break;}
 case'review-wrong':{const ids=reviewItems('错题');if(!ids.length){toast('当前筛选没有错题');break;}startQuiz('wrong',filterLevel,reviewCount,ids);break;}
 case'book-view':bookView=id;page=1;selectedWords.clear();render();break;
 case'book-select-page':bookItems().slice((page-1)*24,page*24).forEach(x=>selectedWords.add(x.id));render();break;
 case'book-unselect':selectedWords.clear();render();break;
 case'book-schedule':scheduleIds([...selectedWords]);render();break;
 case'book-flash':case'book-reading':{const allowed=new Set(bookItems().map(x=>x.id));const ids=[...selectedWords].filter(id=>allowed.has(id));if(!ids.length){toast('请先选择单词');break;}startQuiz(a==='book-flash'?'word-flash':'word-reading',filterLevel,ids.length,ids);break;}
 case'book-add':for(const wid of selectedWords){if(!MAP.get(wid)?.word)continue;state.wordbook[wid]=true;SYNC.stamp(state,'wordbook',wid);}save();render();break;
 case'book-remove':for(const wid of selectedWords){delete state.wordbook[wid];SYNC.stamp(state,'wordbook',wid);}save();selectedWords.clear();render();break;
 case'book-export':exportWordbook();break;
 case'book-page':for(const x of filtered(V).slice((page-1)*24,page*24)){state.wordbook[x.id]=true;SYNC.stamp(state,'wordbook',x.id);}save();toast('本页词条已加入单词本');render();break;
 case'review-view':reviewView=id;page=1;render();break;
 case'review-one':startQuiz(state.wrong[id]?'wrong':'due','全部',1,[id]);break;
 case'wrong-clear':delete state.wrong[id];SYNC.stamp(state,'wrong',id);save();render();break;
 case'ruby':state.profile.ruby=!state.profile.ruby;SYNC.stamp(state,'profile','ruby');save();render();break;
 case'theme':state.profile.light=!state.profile.light;SYNC.stamp(state,'profile','light');prefs();save();if(route==='settings')render();break;
 case'export':exportSave();break;
 case'export-raw':try{download('kotobapath-original-backup.json',localStorage.getItem(key)||'{}');}catch(e){toast('无法访问原始存档。');}break;
 case'resolve-storage':try{download('kotobapath-original-backup.json',localStorage.getItem(key)||'{}');storageProblem='';save();render();}catch(e){toast('无法读取存档，请先允许本地存储并导出当前进度。');}break;
 case'import':$('#import-file').click();break;
 case'apply-import':if(pendingImport){
  try{const candidate=validateSave(importCandidate());exportSave();const prev=state,oldProblem=storageProblem;state=candidate;storageProblem='';
   if(save()){pendingImport=null;$('#detail').close();quiz=null;clearInterval(sessionTimer);render();toast('存档已同步，文本冲突副本可在设置中导出');}
   else{state=prev;storageProblem=oldProblem;toast('保存失败，已保留原进度，未应用导入。');}
  }catch(e){toast('同步失败：'+e.message);}
 }break;
 case'export-conflicts':download('kotobapath-conflict-copies-'+today()+'.json',JSON.stringify(state.sync.conflicts,null,2));break;
 case'export-upgrade-backup':try{const raw=localStorage.getItem('kotobapath.backup.before.1.2.0');if(raw)download('kotobapath-pre-1.2.0.json',raw);else toast('本机没有升级前备份；可直接导出当前存档。');}catch(e){toast('无法读取升级前备份。');}break;
 case'export-draft':{const w=MAP.get(id);download('kotobapath-'+w.level+'-'+id+'.txt',w.title+'\n\n'+(state.drafts[id]||''),'text/plain;charset=utf-8');break;}
 case'export-summary':download('kotobapath-progress-'+today()+'.txt','KotobaPath 学习摘要\n'+today()+'\n当前路线：'+state.profile.level+'\n已掌握：'+Object.keys(state.learned).length+'\n收藏：'+Object.keys(state.stars).length+'\n学习天数：'+Object.keys(state.days).length+'\n自评进度不代表JLPT能力认定。','text/plain;charset=utf-8');break;
 case'reset-prompt':$('#modal-body').innerHTML='<h1>重置学习进度</h1><p>输入 RESET 确认。当前进度会先生成备份下载。</p><input id="reset-confirm" aria-label="输入RESET" autocomplete="off">'+btn('备份并重置','reset-confirm','','danger');$('#detail').showModal();break;
 case'reset-confirm':if($('#reset-confirm').value==='RESET'){exportSave();state=SYNC.upgrade(blankState());storageProblem='';save();quiz=null;clearInterval(sessionTimer);$('#detail').close();render();toast('已重置进度。');}else toast('输入不匹配，未重置。');break;
 }
});
function nextQ(){if(!quiz?.answered)return;quiz.index++;quiz.answered=false;quiz.given='';quiz.flipped=false;quiz.selected=[];quiz.tokens=null;render();window.scrollTo({top:0,behavior:'smooth'});}
let searchTimeout;
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){if(e.isComposing)return;const pos=t.selectionStart;search=t.value;page=1;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{render();const x=$('#search');x?.focus();try{x?.setSelectionRange(pos,pos);}catch(e){}},150);}if(t.id==='item-note'){state.notes[t.dataset.id]=t.value;SYNC.stamp(state,'notes',t.dataset.id);save();}if(t.id==='draft'){state.drafts[t.dataset.id]=t.value;SYNC.stamp(state,'drafts',t.dataset.id);save();$('#draft-analysis').innerHTML=draftAnalysis(t.value,MAP.get(t.dataset.id));}if(t.id==='pref-font'){state.profile.font=Number(t.value);SYNC.stamp(state,'profile','font');prefs();t.nextElementSibling.textContent=t.value+'px';save();}});
document.addEventListener('compositionend',e=>{if(e.target.id==='search')e.target.dispatchEvent(new Event('input',{bubbles:true}));});
document.addEventListener('change',e=>{const t=e.target;if(t.matches?.('.word-select')){t.checked?selectedWords.add(t.dataset.id):selectedWords.delete(t.dataset.id);const out=$('#selection-count');if(out)out.textContent=selectedWords.size;}if(t.id==='review-kind'){reviewKind=t.value;page=1;render();}if(t.id==='review-sort'){reviewSort=t.value;page=1;render();}if(t.id==='review-count'){reviewCount=Number(t.value);}if(t.id==='reading-status'){readingStatus=t.value;page=1;render();}if(t.id==='reading-genre'){readingGenre=t.value;page=1;render();}if(t.id==='only'){only=t.value;page=1;render();}if(t.id==='writing-select'){writingId=t.value;render();}if(t.id==='pref-level'){state.profile.level=t.value;SYNC.stamp(state,'profile','level');save();}if(t.id==='pref-daily'){state.profile.daily=Number(t.value);SYNC.stamp(state,'profile','daily');save();}if(t.id==='import-mode'||t.id==='import-policy')refreshImportPreview();if(t.id==='import-file'){importFile(t.files[0]);t.value='';}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.keyCode===229||$('#detail').open)return;const active=document.activeElement;if(e.key==='Enter'&&active?.dataset.act&&active.tagName!=='BUTTON'&&active.tagName!=='A'){active.click();return;}if(route!=='practice'||!quiz||quiz.finished||quiz.index>=quiz.questions.length)return;const q=quiz.questions[quiz.index];if(e.key==='Enter'){if(quiz.answered){e.preventDefault();nextQ();}else if(q.type==='input'&&active?.id==='quiz-input'){e.preventDefault();if(active.value.trim())submit(active.value);}}else if(q.type==='choice'&&!quiz.answered&&/^[1-4]$/.test(e.key)&&!['INPUT','TEXTAREA','SELECT'].includes(active?.tagName)){const a=q.options[Number(e.key)-1];if(a)submit(a);}});
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
$('#theme').onclick=()=>{state.profile.light=!state.profile.light;SYNC.stamp(state,'profile','light');prefs();save();};$('#export-top').onclick=exportSave;$('#close-modal').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#detail').addEventListener('close',()=>{if(!quiz||route!=='practice')render();});
$('#menu').onclick=()=>document.body.classList.toggle('menu-open');
window.addEventListener('hashchange',()=>{clearTimeout(searchTimeout);resetFilters();if(pendingFilter){filterLevel=pendingFilter;pendingFilter=null;}document.body.classList.remove('menu-open');if($('#detail').open)$('#detail').close();if(location.hash.slice(1).split('?')[0]==='home'||!location.hash)chooseHomeQuote();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===key){storageProblem='另一标签页更改了存档。为避免互相覆盖，请导出当前进度后刷新页面。';$('#save-status').textContent='其他标签页已更改存档';$('#save-status').classList.add('save-error');toast(storageProblem);}});
try{const raw=localStorage.getItem(key);if(raw){const original=JSON.parse(raw);state=validateSave(original);if(original.appVersion!==SYNC.VERSION){if(!localStorage.getItem('kotobapath.backup.before.1.2.0'))localStorage.setItem('kotobapath.backup.before.1.2.0',raw);}if(original.appVersion!==SYNC.VERSION||original.contentVersion!==SYNC.CONTENT_VERSION)localStorage.setItem(key,JSON.stringify(state));}}catch(e){storageProblem='存档读取或升级备份失败。已停止自动覆盖，请先在设置导出原始备份。';}
render();if(storageProblem){$('#save-status').textContent='存档读取异常';toast(storageProblem);}
